from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_depth(paren_substring: str) -> int:
        depth, max_depth = 0, 0
        for char in paren_substring:
            if char == '(':
                depth += 1
                max_depth = max(max_depth, depth)
            elif char == ')':
                depth -= 1
        return max_depth

